SELECT u.id, recent.id AS order_id FROM users u LEFT JOIN LATERAL (SELECT id
FROM orders o WHERE o.user_id = u.id ORDER BY created_at DESC,
id DESC LIMIT 1) recent ON true;

SELECT id, SUM(amount) OVER (ORDER BY created_at,
id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_total FROM
orders;

INSERT INTO users (name, email) VALUES ('New',
'pomo@example.com') ON CONFLICT (email) DO UPDATE SET name = EXCLUDED.name
RETURNING id, name;

MERGE INTO users u USING (VALUES ('pomo@example.com', 'Pomo')) AS s(email,
name) ON u.email = s.email WHEN MATCHED THEN UPDATE SET name = s.name WHEN NOT
MATCHED THEN INSERT (email, name) VALUES (s.email, s.name);
